node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get booking details
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('=== BOOKING ===');
console.log(JSON.stringify(booking, null, 2));

// Get the flight details
if (booking) {
  const flight = db.prepare('SELECT * FROM flights WHERE flight_id = ?').get(booking.flight_id);
  console.log('\n=== FLIGHT ===');
  console.log(JSON.stringify(flight, null, 2));

  // Also check flights_json
  if (booking.flights_json) {
    const flights = JSON.parse(booking.flights_json);
    console.log('\n=== FLIGHTS_JSON ===');
    console.log(JSON.stringify(flights, null, 2));
    for (const f of flights) {
      const fn = f.flight_number || f.flight_id;
      if (fn) {
        const fd = db.prepare('SELECT * FROM flights WHERE flight_id = ?').get(fn);
        console.log('\nFlight detail for', fn, ':', JSON.stringify(fd, null, 2));
      }
    }
  }
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for all flights from JFK to LHR on 2026-10-15
const flights = db.prepare(\"SELECT * FROM flights WHERE origin = 'JFK' AND destination = 'LHR'\").all();
console.log('=== ALL JFK -> LHR FLIGHTS ===');
for (const f of flights) {
  const prices = JSON.parse(f.cabin_prices_json);
  const dates = JSON.parse(f.dates_json);
  console.log('Flight:', f.flight_id, '| Departure:', f.departure_time, '| Arrival:', f.arrival_time, '| Status:', f.status);
  console.log('  Business price:', prices.business);
  console.log('  Dates:', Object.keys(dates).join(', '));
  console.log();
}
"
